import{_ as t,o as n,c as s,ah as o}from"./chunks/framework.C-FRNfAJ.js";const g=JSON.parse('{"title":"Suivi et contrôle","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/administrateur/suivi.md","filePath":"src/guide/administrateur/suivi.md"}'),a={name:"guide/administrateur/suivi.md"};function r(i,e,c,u,l,d){return n(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="suivi-et-controle" tabindex="-1">Suivi et contrôle <a class="header-anchor" href="#suivi-et-controle" aria-label="Permalink to &quot;Suivi et contrôle&quot;">​</a></h1><h2 id="la-synchronisation-seve" tabindex="-1">La synchronisation Sève <a class="header-anchor" href="#la-synchronisation-seve" aria-label="Permalink to &quot;La synchronisation Sève&quot;">​</a></h2><p><strong>Administration → Synchronisation Sève</strong> montre les appels que Kura envoie à Sève : ouverture du compte, statut du compte (actif, suspendu, Canopé), inscription au cours, retrait du cours.</p><p>Chaque appel est <strong>en attente</strong>, <strong>en échec</strong> ou <strong>envoyé</strong>. Les appels d&#39;un même compte partent <strong>dans l&#39;ordre</strong> : un appel en échec retient les suivants de ce compte.</p><ul><li>Un échec est <strong>réessayé</strong> automatiquement, à des intervalles de plus en plus espacés. La page indique le nombre d&#39;essais et le prochain.</li><li>Au <strong>cinquième échec</strong> d&#39;un appel, les Administrateurs sont <strong>alertés</strong>.</li><li><strong>Réessayer</strong> relance un appel sans attendre.</li><li>Un compte que Moodle connaît déjà est retrouvé, pas créé en double.</li><li>Tant que Sève n&#39;est pas configuré, les appels attendent, et la page l&#39;indique.</li></ul><p>Si un apprenant dit ne pas avoir accès à Sève, c&#39;est ici que l&#39;on regarde si son ouverture de compte ou son inscription au cours est bloquée. Un apprenant n&#39;est inscrit à un cours que si le Coordinateur a renseigné <strong>l&#39;identifiant du cours Sève de la cohorte</strong>.</p><h2 id="le-journal-d-audit" tabindex="-1">Le journal d&#39;audit <a class="header-anchor" href="#le-journal-d-audit" aria-label="Permalink to &quot;Le journal d&#39;audit&quot;">​</a></h2><p><strong>Administration → Journal d&#39;audit</strong> conserve toutes les <strong>actions sensibles</strong>, dans l&#39;ordre : validations et retraits de rôles, transformations de comptes, modifications d&#39;utilisateurs, changements de consentements, signatures, délivrances de certificats, corrections de présence, etc.</p><p>Chaque entrée porte sa date, son <strong>action</strong>, son <strong>auteur</strong> (ou « Système »), sa <strong>cible</strong>, le <strong>canal</strong> et les <strong>détails</strong> (valeurs avant et après). Filtrez par action ou par auteur.</p><p><strong>Le journal ne peut pas être modifié</strong> : aucune entrée ne s&#39;efface ni ne se corrige. Les actions des comptes à privilèges (Coordinateur, Direction, Administrateur) sur les comptes et les rôles y sont toujours consignées.</p><h2 id="les-envois-et-les-echecs-de-notification" tabindex="-1">Les envois et les échecs de notification <a class="header-anchor" href="#les-envois-et-les-echecs-de-notification" aria-label="Permalink to &quot;Les envois et les échecs de notification&quot;">​</a></h2><p>Le <strong>journal des envois</strong> de <strong>Formation → Communication</strong> montre ce que le moteur de notifications a envoyé, canal par canal, avec les échecs (voir <a href="./../coordinateur/communication.html#le-journal-des-envois">Communication</a>). Un échec d&#39;un canal n&#39;empêche pas les autres.</p>',12)])])}const m=t(a,[["render",r]]);export{g as __pageData,m as default};
